import{_ as a,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const e="/ascendc.github.io/assets/set_flag_wait_flag_sequence_diagram.BQvAlubN.png",l="/ascendc.github.io/assets/mutex_lock_unlock_sequence_diagram.aH7e28St.png",I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"高级核函数编程","link":"/guide/programming_guide/advanced_programming/advanced_kernel_programming/advanced_kernel_programming"},{"text":"核内同步","link":"/guide/programming_guide/advanced_programming/advanced_kernel_programming/intra_core_sync/intra_core_sync"},{"text":"基于Mutex实现多流水同步","link":"/guide/programming_guide/advanced_programming/advanced_kernel_programming/intra_core_sync/mutex_multi_pipeline_sync"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/advanced_kernel_programming/intra_core_sync/mutex_multi_pipeline_sync.md","filePath":"guide/programming_guide/advanced_programming/advanced_kernel_programming/intra_core_sync/mutex_multi_pipeline_sync.md","outlineHeaders":[{"level":2,"title":"总述","slug":"总述","link":"#总述"},{"level":2,"title":"双缓冲算子的多流水数据依赖","slug":"双缓冲算子的多流水数据依赖","link":"#双缓冲算子的多流水数据依赖"},{"level":2,"title":"MutexID规划","slug":"MutexID规划","link":"#MutexID规划"},{"level":2,"title":"Mutex与其他核内同步接口","slug":"Mutex与其他核内同步接口","link":"#Mutex与其他核内同步接口"},{"level":3,"title":"Lock/Unlock与SetFlag/WaitFlag的功能","slug":"Lock/Unlock与SetFlag/WaitFlag的功能","link":"#Lock/Unlock与SetFlag/WaitFlag的功能"},{"level":3,"title":"两组接口针对正向数据依赖和反向数据依赖的同步方式差异","slug":"两组接口针对正向数据依赖和反向数据依赖的同步方式差异","link":"#两组接口针对正向数据依赖和反向数据依赖的同步方式差异"},{"level":2,"title":"使用约束","slug":"使用约束","link":"#使用约束"}],"lastUpdated":1790681687000}'),o={name:"guide/programming_guide/advanced_programming/advanced_kernel_programming/intra_core_sync/mutex_multi_pipeline_sync.md"};function d(t,s,i,r,_,u){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>基于Mutex实现多流水同步</h1><h2 id="总述">总述<a class="header-anchor" href="#总述">​</a></h2><p>当矢量算子的数据搬入、矢量计算和数据搬出等不同流水之间存在数据依赖时，通过<code>Mutex</code>建立流水同步关系，使不同流水中存在数据依赖的操作串行执行，可以避免不同流水并发访问同一资源时产生数据错误。</p><p>本文以Basic API中的<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/Mutex_ISASI.html">Mutex::Lock</a>和<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/Mutex_ISASI.html">Mutex::Unlock</a>为例，说明使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/03_basic_api/05_sync_control/mutex/README.md">Mutex实现双缓冲多流水同步</a>的原理。相关同步原理同样适用于C API中的<a href="../../../../../api/SIMD-API/c_api/sync/intra_core_sync/asc_lock.html">asc_lock</a>和<a href="../../../../../api/SIMD-API/c_api/sync/intra_core_sync/asc_unlock.html">asc_unlock</a>。C API双缓冲样例请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/02_features/01_reg_vector_compute/00_add_double_buffer/README.md">add_double_buffer样例</a>。</p><p>本文首先介绍双缓冲算子中的正向数据依赖和反向数据依赖，然后说明如何规划<code>MutexID</code>并建立流水同步关系，接着通过<code>Lock</code>/<code>Unlock</code>与<code>SetFlag</code>/<code>WaitFlag</code>的对比说明<code>Mutex</code>的使用方式，最后介绍<code>Mutex</code>接口的使用约束。</p><h2 id="双缓冲算子的多流水数据依赖">双缓冲算子的多流水数据依赖<a class="header-anchor" href="#双缓冲算子的多流水数据依赖">​</a></h2><p>一个典型的矢量算子包含数据搬入、矢量计算和数据搬出三个阶段，分别使用<code>PIPE_MTE2</code>、<code>PIPE_V</code>和<code>PIPE_MTE3</code>流水。数据量超过Unified Buffer（UB）容量时，算子通常将数据切分为多个切片，并循环处理这些切片。</p><p>采用<a href="../../../../operator_practice/simd_operator_impl/vector_programming/double_buffer_scenario.html">双缓冲</a>后，两组Buffer资源交替使用。当前切片使用一组资源进行计算时，其他流水可以使用另一组资源处理相邻切片。</p><p>同一切片中的流水存在正向数据依赖，需要通过流水同步保证处理顺序：</p><ul><li><code>PIPE_MTE2 -&gt; PIPE_V</code>：数据搬入完成后，<code>PIPE_V</code>才能读取该切片的数据并进行计算。</li><li><code>PIPE_V -&gt; PIPE_MTE3</code>：计算完成后，<code>PIPE_MTE3</code>才能搬出计算结果。</li></ul><p>Buffer复用时还会产生反向数据依赖。第<code>i + 2</code>轮重新使用第<code>i</code>轮的同一组Buffer资源时，需要通过流水同步满足以下约束：</p><ul><li><code>PIPE_V -&gt; PIPE_MTE2</code>：第<code>i</code>轮的计算完成后，第<code>i + 2</code>轮才能覆盖输入Buffer。</li><li><code>PIPE_MTE3 -&gt; PIPE_V</code>：第<code>i</code>轮的结果搬出完成后，第<code>i + 2</code>轮才能覆盖输出Buffer。</li></ul><p>针对正向数据依赖建立的流水同步关系，可以保证同一切片内的处理顺序；针对反向数据依赖建立的流水同步关系，可以保证Buffer复用时不会覆盖仍被前序流水访问的数据。关于如何通过流水同步解决以上两种数据依赖关系的原理，更详细的描述请参考以下文档：</p><ul><li><a href="../../../programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html#%E5%90%8C%E6%AD%A5%E7%AE%A1%E7%90%86">静态Tensor编程方式的同步管理</a></li><li><a href="../../memory_model/memory_consistency.html#%E8%B7%A8%E6%B5%81%E6%B0%B4%E5%86%85%E5%AD%98%E4%B8%80%E8%87%B4%E6%80%A7">内存一致性中的跨流水内存一致性</a></li></ul><h2 id="MutexID规划">MutexID规划<a class="header-anchor" href="#MutexID规划">​</a></h2><p>开发者需要根据流水间的数据依赖关系规划用于同步的<code>MutexID</code>：处理同一组Buffer资源且存在数据依赖的流水使用相同的<code>MutexID</code>，不同的资源组使用不同的<code>MutexID</code>。例如，Add算子的<code>xLocal</code>、<code>yLocal</code>和<code>zLocal</code>组成一组资源。</p><p>双缓冲使用两组Buffer资源和两个<code>MutexID</code>：</p><ul><li>循环第<code>i</code>轮选择<code>bufferIndex = i % 2</code>，使同一个<code>MutexID</code>只管理其对应资源组的流水同步。</li><li>第<code>i + 2</code>轮再次选择相同的资源组和<code>MutexID</code>，此时<code>PIPE_MTE2</code>上的<code>Lock</code>会等待此前所有使用该<code>MutexID</code>的流水均已<code>Unlock</code>，其中包括第<code>i</code>轮<code>PIPE_MTE3</code>的<code>Unlock</code>，从而满足反向数据依赖，保证资源能够安全复用。</li></ul><table><thead><tr><th>轮次</th><th>Buffer资源组</th><th><code>MutexID</code></th><th>关键约束</th></tr></thead><tbody><tr><td><code>i</code></td><td><code>buffer0</code></td><td><code>mutexId0</code></td><td><code>PIPE_MTE2</code>、<code>PIPE_V</code>、<code>PIPE_MTE3</code>按顺序处理当前切片。</td></tr><tr><td><code>i + 1</code></td><td><code>buffer1</code></td><td><code>mutexId1</code></td><td>使用另一组资源，可以与第<code>i</code>轮的异步流水重叠。</td></tr><tr><td><code>i + 2</code></td><td><code>buffer0</code></td><td><code>mutexId0</code></td><td><code>PIPE_MTE2</code>搬入前等待第<code>i</code>轮的资源释放，避免覆盖<code>buffer0</code>。</td></tr></tbody></table><p><code>MutexID</code>的获取和释放方式与编程范式有关，完整约束请参考<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/Lock.html#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">Lock约束说明</a>：</p><ul><li>TPipe-TQue框架编程范式需要通过<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/AllocMutexID_ISASI.html">AllocMutexID</a>申请，并在使用结束后通过<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/ReleaseMutexID_ISASI.html">ReleaseMutexID</a>释放。</li><li>静态Tensor编程范式下，<code>MutexID</code>可以通过<code>AllocMutexID</code>/<code>ReleaseMutexID</code>申请释放，也可以由开发者自行管理；自行管理时需要保证<code>MutexID</code>不与其他同步或资源管理接口使用的<code>MutexID</code>冲突，建议使用0-27，28-31为系统内部规划预留，不建议使用。</li></ul><h2 id="Mutex与其他核内同步接口">Mutex与其他核内同步接口<a class="header-anchor" href="#Mutex与其他核内同步接口">​</a></h2><h3 id="Lock/Unlock与SetFlag/WaitFlag的功能">Lock/Unlock与SetFlag/WaitFlag的功能<a class="header-anchor" href="#Lock/Unlock与SetFlag/WaitFlag的功能">​</a></h3><p><code>Lock</code>和<code>Unlock</code>必须配合使用，接口的功能如下：</p><ul><li><code>Lock</code>根据<code>MutexID</code>获取<code>Mutex</code>；如果<code>Mutex</code>已被锁定，将阻塞指定流水上的后续指令，直到此前所有流水中使用相同<code>MutexID</code>的<code>Mutex</code>都已通过<code>Unlock</code>释放。</li><li><code>Unlock</code>在指定流水的前序指令执行完成后，根据<code>MutexID</code>释放对应<code>Mutex</code>。</li></ul><p><code>SetFlag</code>和<code>WaitFlag</code>也必须配合使用，接口的功能如下：</p><ul><li><code>SetFlag</code>在源流水的前序指令完成后设置对应标志位，但不会阻塞源流水的后续指令。</li><li><code>WaitFlag</code>执行时，如果标志位为0，则阻塞目的流水的后续指令，如果标志位为1，则清除标志位并继续执行。</li></ul><p>图1和图2以<code>PIPE_MTE2</code>与<code>PIPE_V</code>之间的同步为例，对比两组接口实现同步的原理：</p><ul><li>图1中，<code>SetFlag</code>/<code>WaitFlag</code>通过设置和等待事件标志位，使<code>PIPE_V</code>在<code>PIPE_MTE2</code>完成前序指令后继续执行。</li><li>图2中，<code>Lock</code>/<code>Unlock</code>通过释放和获取同一个<code>Mutex</code>，使<code>PIPE_V</code>在<code>PIPE_MTE2</code>完成前序指令并释放<code>Mutex</code>后获取<code>Mutex</code>、继续执行。</li></ul><p>对比图中的等待、状态变化和解除阻塞过程，可以理解两组接口如何通过不同机制解决不同流水间的数据依赖。</p><p><strong>图1</strong> <code>SetFlag</code>/<code>WaitFlag</code>同步时序示意图<br><img src="'+e+'" alt></p><p><strong>图2</strong> <code>Lock</code>/<code>Unlock</code>同步时序示意图<br><img src="'+l+`" alt></p><h3 id="两组接口针对正向数据依赖和反向数据依赖的同步方式差异">两组接口针对正向数据依赖和反向数据依赖的同步方式差异<a class="header-anchor" href="#两组接口针对正向数据依赖和反向数据依赖的同步方式差异">​</a></h3><p><code>Mutex</code>将<code>MutexID</code>与一组Buffer资源绑定，记录该资源此前各阶段的完成状态。每个阶段只需要锁定当前流水：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">loopCount</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">bufferIndex</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutexId</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">bufferIndex</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">mutexId0</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">mutexId1</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// 等待当前资源组此前的访问完成，然后搬入当前切片。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// PIPE_MTE2搬入当前切片的数据。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 等待PIPE_MTE2完成，然后计算当前切片。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// PIPE_V计算当前切片。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 等待PIPE_V完成，然后搬出计算结果。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Lock</span><span class="o">&lt;</span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// PIPE_MTE3搬出当前切片的结果。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Mutex</span><span class="o">::</span><span class="n">Unlock</span><span class="o">&lt;</span><span class="n">PIPE_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">mutexId</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>在第<code>i + 2</code>轮复用同一组资源时，<code>PIPE_MTE2</code>和<code>PIPE_V</code>再次<code>Lock</code>同一个<code>MutexID</code>，会统一等待此前所有使用该<code>MutexID</code>的流水完成。因此，代码不需要在当前调用中指定前序流水，也不需要分别针对<code>PIPE_V -&gt; PIPE_MTE2</code>和<code>PIPE_MTE3 -&gt; PIPE_V</code>等反向数据依赖建立同步关系。</p><p>如果使用<code>SetFlag</code>/<code>WaitFlag</code>，则需要针对每一组从源流水到目的流水的数据依赖分别建立同步关系。下面代码只保留同步相关的核心逻辑，数据搬入、计算和搬出操作用注释表示：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">loopCount</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">bufferIndex</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">BUFFER_NUM</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 复用输入资源前，等待同一资源组的上一轮（第i-2轮）PIPE_V完成：PIPE_V -&gt; PIPE_MTE2。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">V_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventVToMTE2</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="c1">// PIPE_MTE2搬入当前切片的数据。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventMTE2ToV</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE2_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventMTE2ToV</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>

<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">BUFFER_NUM</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 复用输出资源前，等待同一资源组的上一轮（第i-2轮）PIPE_MTE3完成：PIPE_MTE3 -&gt; PIPE_V。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE3_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventMTE3ToV</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="c1">// PIPE_V计算当前切片。</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BUFFER_NUM</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">loopCount</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 只有后续仍会复用输入资源时，才设置PIPE_V -&gt; PIPE_MTE2事件。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">V_MTE2</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventVToMTE2</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">V_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventVToMTE3</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">WaitFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">V_MTE3</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventVToMTE3</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>

<span class="w">    </span><span class="c1">// PIPE_MTE3搬出当前切片的结果。</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">i</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">BUFFER_NUM</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">loopCount</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 只有后续仍会复用输出资源时，才设置PIPE_MTE3 -&gt; PIPE_V事件。</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">SetFlag</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HardEvent</span><span class="o">::</span><span class="n">MTE3_V</span><span class="o">&gt;</span><span class="p">(</span><span class="n">eventMTE3ToV</span><span class="p">[</span><span class="n">bufferIndex</span><span class="p">]);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p><code>SetFlag</code>/<code>WaitFlag</code>需要针对正向数据依赖和反向数据依赖分别选择<code>HardEvent</code>并管理事件ID，以建立对应的流水同步关系，还需要根据循环的开始和结束位置判断反向事件是否存在。相比之下，<code>Mutex</code>不需要传入源流水和目的流水组合，只需在当前流水上使用相同<code>MutexID</code>，即可同步管理同一组资源的多流水生命周期。</p><p>此外，<code>SetFlag</code>/<code>WaitFlag</code>通过<code>HardEvent</code>表示源流水到目的流水的同步关系。不同硬件架构支持的<code>HardEvent</code>组合可能不同，使用<code>SetFlag</code>/<code>WaitFlag</code>时需要根据目标架构确认对应的<code>HardEvent</code>组合是否存在。</p><h2 id="使用约束">使用约束<a class="header-anchor" href="#使用约束">​</a></h2><p>使用<code>Mutex</code>时需要遵守以下约束，完整内容请以<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/Lock.html#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">Lock约束说明</a>和<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/Unlock.html#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">Unlock约束说明</a>为准：</p><ul><li>对同一个<code>MutexID</code>，<code>Lock</code>和<code>Unlock</code>必须严格成对出现，并使用相同的流水类型和<code>MutexID</code>；对应的<code>Unlock</code>必须位于<code>Lock</code>之后。</li><li>对于相同<code>MutexID</code>的<code>Lock</code>/<code>Unlock</code>组合，无论流水类型是否相同，都不得嵌套使用，否则属于未定义行为。</li><li>连续使用相同<code>MutexID</code>和相同流水类型的<code>Lock</code>/<code>Unlock</code>，不能实现同一流水内不同指令之间的同步。同一流水内需要保证不同指令的执行顺序时，应使用<a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier</a>建立单个流水内的同步关系。</li><li>TPipe-TQue框架编程范式下，通过<code>AllocMutexID</code>申请的<code>MutexID</code>使用结束后应及时通过<code>ReleaseMutexID</code>释放，避免<code>MutexID</code>耗尽。</li><li>同一组Buffer资源的所有相关流水应使用相同<code>MutexID</code>，不同资源组应使用不同<code>MutexID</code>。</li></ul></article></div>`,1)])])}const E=a(o,[["render",d]]);export{I as __pageData,E as default};
